/* eslint-disable */
import React from "react";

/* ---------- IMAGES (mets-les dans src/assets/img/) ---------- */
import IconMenu from "assets/img/menu.png";
import IconRes from "assets/img/ressources.png";
import IconRH from "assets/img/rh.png";
import IconSales from "assets/img/commercial.png";
import IconOps from "assets/img/moyens.png";    // ajoute-la si tu l'as
import IconTrain from "assets/img/formation.png"; // ajoute-la si tu l'as

import News1 from "assets/img/newdeal.jpg";
import News2 from "assets/img/sim.jpg";
import News3 from "assets/img/mbaye.png"; // peut servir en “actu”
import CEO from "assets/img/mbaye.png";
import Team from "assets/img/team.png";

/* ---------- PETIT CALENDRIER (style maquette, sans dépendance) ---------- */
function PrettyCalendar({
    year = 2023,
    month = 2,          // 1..12
    selectedDay = 20,
    title = "Un jour spécial pour ?",
    birthdayLabel = "Anniversaire de Ousmane DIA",
}) {
    const monthIndex = month - 1;
    const monthName = new Date(year, monthIndex, 1).toLocaleString("en-US", { month: "long" });
    const firstWeekday = new Date(year, monthIndex, 1).getDay(); // 0=Sun..6=Sat
    const daysInMonth = new Date(year, month, 0).getDate();
    const cells = [
        ...Array(firstWeekday).fill(null),
        ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
    ];
    while (cells.length % 7 !== 0) cells.push(null);
    const weekLabels = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

    return (
        <div>
            <h3 className="text-[#1c2b68] font-semibold text-2xl mb-3">{title}</h3>

            <div className="bg-white rounded-[20px] shadow-md p-5">
                <div className="text-center">
                    <div className="uppercase tracking-wide text-2xl md:text-3xl text-blueGray-600">
                        {monthName.toUpperCase()} {year}
                    </div>
                </div>

                <div className="mt-4 bg-blueGray-100 rounded-full px-3 py-2">
                    <div className="grid grid-cols-7 text-center text-[12px] md:text-[13px] font-semibold">
                        {weekLabels.map((w, i) => (
                            <div key={w} className={`py-1 ${i === 0 ? "text-red-500" : "text-blueGray-500"}`}>{w}</div>
                        ))}
                    </div>
                </div>

                <div className="mt-4 grid grid-cols-7 gap-y-4">
                    {cells.map((v, idx) => {
                        const col = idx % 7;
                        const isSunday = col === 0;
                        const isSel = v === selectedDay && v !== null;
                        return (
                            <div key={idx} className="h-8 flex items-center justify-center">
                                {v === null ? <span className="text-blueGray-300"> </span> : (
                                    <div className={`w-10 h-10 flex items-center justify-center ${isSel ? "bg-[#e8b6b6] rounded-[6px]" : ""}`}>
                                        <span className={`${isSunday ? (isSel ? "text-[#6b1410]" : "text-red-500") : (isSel ? "text-[#6b1410]" : "text-blueGray-600")} text-[15px]`}>
                                            {v}
                                        </span>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="mt-5 flex items-center justify-between">
                <span className="text-blueGray-800 font-semibold text-lg md:text-xl">{birthdayLabel}</span>
                <span role="img" aria-label="party" className="text-2xl md:text-3xl">🎉</span>
            </div>
        </div>
    );
}

/* ---------- SECTION PRINCIPALE ---------- */
export default function DashboardShowcase() {
    const topIcons = [
        { img: IconMenu, label: "Restauration" },
        { img: IconRes, label: "Ressources" },
        { img: IconRH, label: "RH" },
        { img: IconSales, label: "Commercial" },
        { img: IconOps, label: "Moyens généraux" },
        { img: IconTrain, label: "Formation" },
    ].filter(Boolean); // enlève ceux que tu n'as pas encore

    return (
        <section className="bg-white">
            <div className="container mx-auto px-4">
                {/* ------- Ligne d’icônes ------- */}
                <div className="flex flex-wrap justify-center gap-6 md:gap-10 lg:gap-14 pt-6 pb-10">
                    {topIcons.map((it, idx) => (
                        <div key={idx} className="w-32">
                            <div className="bg-white rounded-2xl shadow-lg px-4 pt-4 pb-3 flex flex-col items-center">
                                <img src={it.img} alt={it.label} className="w-10 h-10 object-contain mb-2" />
                            </div>
                            <div className="mt-2 text-center text-[15px] text-blueGray-800 font-medium">
                                {it.label}
                            </div>
                        </div>
                    ))}
                </div>

                {/* ------- Grille deux colonnes ------- */}
                <div className="grid grid-cols-12 gap-8 lg:gap-10 pb-16">
                    {/* Colonne gauche */}
                    <div className="col-span-12 lg:col-span-7 space-y-10">
                        {/* Calendrier + Actualités */}
                        <div className="grid grid-cols-12 gap-6">
                            {/* Calendrier */}
                            <div className="col-span-12 md:col-span-6">
                                <PrettyCalendar year={2023} month={2} selectedDay={20} />
                            </div>

                            {/* Actualités (pile d’images) */}
                            <div className="col-span-12 md:col-span-6">
                                <h3 className="text-[#1c2b68] font-semibold text-2xl mb-3">Actualités</h3>
                                <div className="relative h-80">
                                    <img src={News1} alt="News1" className="absolute top-0 right-0 w-72 h-44 object-cover rounded-xl shadow-xl" />
                                    <img src={News2} alt="News2" className="absolute top-10 right-10 w-64 h-40 object-cover rounded-xl shadow-xl" />
                                    <img src={News3} alt="News3" className="absolute top-20 right-20 w-72 h-48 object-cover rounded-xl shadow-xl" />
                                </div>
                            </div>
                        </div>

                        {/* Motif + CEO (chevauchement visuel) */}
                        <div className="grid grid-cols-12 gap-6 items-start">
                            {/* Motif à pois + image équipe */}
                            <div className="col-span-12 md:col-span-6">
                                <div
                                    className="rounded-2xl h-48 mb-6"
                                    style={{
                                        backgroundImage:
                                            "radial-gradient(rgba(28,43,104,0.8) 1px, transparent 1px), radial-gradient(rgba(28,43,104,0.35) 1px, transparent 1px)",
                                        backgroundPosition: "0 0, 8px 8px",
                                        backgroundSize: "16px 16px",
                                        backgroundColor: "#f4f6fb",
                                    }}
                                />
                                <div className="rounded-2xl overflow-hidden">
                                    <img src={Team} alt="Team" className="w-full h-72 object-cover" />
                                </div>
                            </div>

                            {/* Carte CEO */}
                            <div className="col-span-12 md:col-span-6">
                                <div className="bg-[#0e173a] rounded-2xl shadow-2xl overflow-hidden relative">
                                    {/* visuel */}
                                    <div className="relative">
                                        <img src={CEO} alt="CEO" className="w-full h-64 object-cover" />
                                        <div className="absolute top-3 right-3 h-[88%] w-1 bg-[#5aa4ff] rounded" />
                                    </div>
                                    {/* contenu */}
                                    <div className="p-6 text-white">
                                        <div className="text-sm tracking-wider font-extrabold uppercase">
                                            Alioune <span className="font-light">MBAYE</span>
                                        </div>
                                        <div className="text-xs opacity-80">CEO ACCEL TECH</div>
                                        <p className="mt-4 text-[15px] leading-relaxed">
                                            “Mon objectif est de montrer que l’Afrique peut produire des solutions
                                            technologiques compétitives et adaptées à ses besoins.”
                                        </p>
                                        <p className="mt-5 text-[13px] opacity-80 italic">
                                            “Transformer nos idées en actions pour bâtir l’héritage de demain.”
